// Verify Razorpay's signature so nobody can post fake payments.
// RAZORPAY_WEBHOOK_SECRET is an n8n environment variable, never stored in this file.
const crypto = require('crypto');
const item = $input.first();
const raw = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body);
const expected = crypto.createHmac('sha256', $env.RAZORPAY_WEBHOOK_SECRET).update(raw).digest('hex');
const received = item.json.headers['x-razorpay-signature'] || '';
const valid = received.length === expected.length && crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
return [{ json: { valid, body: item.json.body } }];

// Map Razorpay's payload to our payments table.
// Notes are set when the payment link / invoice is created:
//   notes.kind = 'program' | 'workshop', notes.invoice_id, notes.workshop_id, notes.lead_id, notes.utm_creative_id
const p = $json.body.payload.payment.entity;
const n = p.notes || {};
const kind = n.kind === 'workshop' ? 'workshop' : 'program';
const problems = [];
if (kind === 'program' && !n.invoice_id) problems.push('programme payment without invoice_id');
if (kind === 'workshop' && !n.workshop_id) problems.push('workshop payment without workshop_id');
return [{ json: {
  razorpay_payment_id: p.id,
  paid_on: new Date(p.created_at * 1000).toISOString().slice(0, 10),
  amount: p.amount / 100,
  kind,
  invoice_id: n.invoice_id || null,
  workshop_id: n.workshop_id || null,
  lead_id: n.lead_id || null,
  utm_creative_id: n.utm_creative_id || null,
  clickup_task_id: n.lead_id || null,
  problems
} }];
